private theorem applyM_sum {ι : Type*} (S : Finset ι)
    (f : ι → Fin n → ℂ) :
    td.applyM (∑ s ∈ S, f s) = ∑ s ∈ S, td.applyM (f s)

private theorem applyM_toComplex_mul (a b : KM n td) :
    td.applyM (toComplex (KM.toFun (a * b))) =
    td.applyM (toComplex (KM.toFun a)) ∘ₕ td.applyM (toComplex (KM.toFun b))

theorem tube_eq_zero_iff_transform {A : TubalMatrix m p n td}
    (i : Fin m) (j : Fin p) :
    A i j = 0 ↔ ∀ k, transform A k i j = 0

theorem sum_normSq_unitary_mulVec {n' : ℕ}
    (W : Matrix (Fin n') (Fin n') ℂ) (hW : IsUnitary W) (v : Fin n' → ℂ) :
    ∑ k, Complex.normSq ((W.mulVec v) k) = ∑ k, Complex.normSq (v k)

private theorem isSVDDiag_realOfSVDDiagC {m' p' : ℕ}
    {S : Matrix (Fin m') (Fin p') ℂ} (hS : IsSVDDiagC S) :
    IsSVDDiag (realOfSVDDiagC S)

private theorem toComplexMatrix_realOfSVDDiagC {m' p' : ℕ}
    {S : Matrix (Fin m') (Fin p') ℂ} (hS : IsSVDDiagC S) :
    toComplexMatrix (realOfSVDDiagC S) = S

private theorem applyM_toComplex_star (a : KM n td) :
    td.applyM (toComplex (KM.toFun (star a))) =
    vecConj (td.applyM (toComplex (KM.toFun a)))

private theorem svd_conj_decomp {m' p' : ℕ}
    {A : Matrix (Fin m') (Fin p') ℂ} {U : Matrix (Fin m') (Fin m') ℂ}
    {S : Matrix (Fin m') (Fin p') ℂ} {V : Matrix (Fin p') (Fin p') ℂ}
    (hS : IsSVDDiagC S) (hdecomp : A = U * S * Vᴴ) :
    matConj A = matConj U * S * (matConj V)ᴴ

private theorem KM_le_of_transform {S : TubalMatrix m p n td}
    {i₁ i₂ : Fin m} {j₁ j₂ : Fin p}
    (him : ∀ k, (transform S k i₁ j₁ - transform S k i₂ j₂).im = 0)
    (hre : ∀ k, 0 ≤ (transform S k i₁ j₁ - transform S k i₂ j₂).re) :
    S i₂ j₂ ≤ S i₁ j₁

private theorem hC_pos_general (td : TubalData n) (k : Fin n)
    (hk_real : IsRealRow td.M k) :
    0 < ∑ i, ((td.M_inv *ᵥ Pi.single k (1 : ℂ)) i).re ^ 2

private theorem conj_pair_multirank_valid (td : TubalData n)
    (h h' : Fin n) (_hh'_ne : h' ≠ h) (hconj : IsConjRow td.M h h') :
    RespectsConjPairing td (fun sl => if sl = h ∨ sl = h' then 1 else 0)

theorem IsFDiagonal.transform_diag {A : TubalMatrix m p n td}
    (hA : IsFDiagonal A) (k : Fin n) (i : Fin m) (j : Fin p)
    (hij : (i : ℕ) ≠ (j : ℕ)) : transform A k i j = 0

theorem isFDiagonal_of_transform {A : TubalMatrix m p n td}
    (h : ∀ (k : Fin n) (i : Fin m) (j : Fin p), (i : ℕ) ≠ (j : ℕ) → transform A k i j = 0) :
    IsFDiagonal A

private lemma commute_toLin'_of_commute_matrix {n : ℕ}
    (A B : Matrix (Fin n) (Fin n) ℝ) (h : A * B = B * A) :
    Commute (mapOfReal A).toLin' (mapOfReal B).toLin'

private lemma aeval_apply_mem_eigenspace {n : ℕ}
    {f : End ℂ (Fin n → ℂ)} {μ : ℂ} {v : Fin n → ℂ}
    (hv : v ∈ f.eigenspace μ) (p : Polynomial ℂ) :
    (Polynomial.aeval f p) v = (p.eval μ) • v

private lemma isFinitelySemisimple_of_isMatDiag {n : ℕ}
    (A : Matrix (Fin n) (Fin n) ℝ) (hA : IsMatDiag A) :
    End.IsFinitelySemisimple (mapOfReal A).toLin'

private theorem frobNormSq_conjTranspose {m' p' : ℕ}
    (A : Matrix (Fin m') (Fin p') ℂ) :
    frobNormSq Aᴴ = frobNormSq A

private theorem col_of_eq {m : ℕ} (S : Matrix (Fin m) (Fin m) ℂ)
    (v : Fin m → Fin m → ℂ) (hv : ∀ i j, S i j = v j i) :
    S.col = v

theorem IsUnitary.conjTranspose_mul_self {n : ℕ} {𝕜 : Type*} [RCLike 𝕜]
    {A : Matrix (Fin n) (Fin n) 𝕜}
    (h : IsUnitary A) : Aᴴ * A = 1

theorem IsUnitary.mul_conjTranspose_self {n : ℕ} {𝕜 : Type*} [RCLike 𝕜]
    {A : Matrix (Fin n) (Fin n) 𝕜}
    (h : IsUnitary A) : A * Aᴴ = 1

theorem IsUnitary.conjTranspose {n : ℕ} {𝕜 : Type*} [RCLike 𝕜]
    {A : Matrix (Fin n) (Fin n) 𝕜}
    (h : IsUnitary A) : IsUnitary Aᴴ

private lemma svdUONB_eq_partialU (A : Matrix (Fin m) (Fin p) 𝕜)
    (i : Fin m) (hi : i ∈ svdActiveSet A) :
    svdUONB A i = svdPartialU A i

private lemma mulVec_svdONB_eq_zero (A : Matrix (Fin m) (Fin p) 𝕜) (j : Fin p)
    (hj : svdEigval A j = 0) :
    A *ᵥ (svdONB A j).ofLp = 0

theorem MatrixSVD.rank_truncApprox_le {m p : ℕ} {A : Matrix (Fin m) (Fin p) ℂ}
    (svd : MatrixSVD A) (k : ℕ) :
    (svd.truncApprox k).rank ≤ k

theorem vecPseudoInv_hasPairedStructure {td : TubalData n} {v : Fin n → ℂ}
    (hv : HasRealPairedStructure td v) :
    HasRealPairedStructure td (vecPseudoInv v)

private theorem mulVec_conj_real_row (M : Matrix (Fin n) (Fin n) ℂ) (c : Fin n → ℂ)
    (i : Fin n) (hreal : IsRealRow M i) :
    ∑ j, M i j * starRingEnd ℂ (c j) = starRingEnd ℂ (∑ j, M i j * c j)

private theorem mulVec_conj_pair_row (M : Matrix (Fin n) (Fin n) ℂ) (c : Fin n → ℂ)
    (i k : Fin n) (hconj : IsConjRow M i k) :
    starRingEnd ℂ (∑ j, M i j * starRingEnd ℂ (c j)) = ∑ j, M k j * c j

private theorem real_row_not_conj_partner (td : TubalData n)
    {i j : Fin n} (hj : IsRealRow td.M j) (hne : i ≠ j)
    (hconj : IsConjRow td.M i j) : False

private theorem single_hasPairedStructure_of_realRow (td : TubalData n)
    {j : Fin n} (hj : IsRealRow td.M j) :
    HasRealPairedStructure td (Pi.single j (1 : ℂ))

private theorem Minv_col_real_of_realRow (td : TubalData n) {j : Fin n}
    (hj : IsRealRow td.M j) :
    ∀ i : Fin n, (td.M_inv i j).im = 0

private theorem Minv_col_conj_of_conjRow (td : TubalData n) {j k : Fin n}
    (hjk : j ≠ k) (hconj : IsConjRow td.M j k) :
    ∀ i : Fin n, td.M_inv i k = starRingEnd ℂ (td.M_inv i j)

theorem Minv_col_conj_of_row_conj (td : TubalData n) {j k : Fin n}
    (h : IsConjRow td.M j k) :
    ∀ i : Fin n, td.M_inv i k = starRingEnd ℂ (td.M_inv i j)

private theorem exists_smul_of_dim_one {W : Submodule ℝ (TubalCarrier n)}
    (hdim : Module.finrank ℝ W = 1) {v : TubalCarrier n} (hv : v ∈ W) (hv_ne : v ≠ 0)
    {a : TubalCarrier n} (ha : a ∈ W) : ∃ α : ℝ, a = α • v

private theorem linearIndependent_cols_of_mul_eq_one {m : ℕ}
    (A B : Matrix (Fin m) (Fin m) ℂ) (h : A * B = 1) :
    LinearIndependent ℂ (col B)

theorem principalIdeal_add {a : TubalCarrier n} {x y : TubalCarrier n}
    (hx : x ∈ principalIdeal tr a) (hy : y ∈ principalIdeal tr a) :
    x + y ∈ principalIdeal tr a

theorem principalIdeal_ideal {a : TubalCarrier n} {x : TubalCarrier n}
    (hx : x ∈ principalIdeal tr a) (y : TubalCarrier n) :
    tr.mul y x ∈ principalIdeal tr a

theorem principalUnit_mul {a x : TubalCarrier n}
    (hx : x ∈ principalIdeal tr a) :
    tr.mul (principalUnit tr a) x = x

theorem principalIdeal_weakInv {a x : TubalCarrier n}
    (hx : x ∈ principalIdeal tr a) :
    tr.weakInv x ∈ principalIdeal tr a

private theorem applyM_starMC_self (td : TubalData n) (u : Fin n → ℂ) :
    td.applyM (starMC td (starConjC td u) u) =
    vecConj (td.applyM u) ∘ₕ td.applyM u

private theorem KM.le_def {td : TubalData n} (a b : KM n td) :
    a ≤ b ↔ (∀ i, (td.applyM (toComplex (KM.toFun b - KM.toFun a)) i).im = 0) ∧
             (∀ i, 0 ≤ (td.applyM (toComplex (KM.toFun b - KM.toFun a)) i).re)

theorem applyM_conj_row {td : TubalData n} {a : Fin n → ℝ} {i k : Fin n}
    (hconj : IsConjRow td.M i k) :
    td.applyM (toComplex a) k = starRingEnd ℂ (td.applyM (toComplex a) i)

theorem vecHadamard_hasPairedStructure {td : TubalData n} {u v : Fin n → ℂ}
    (hu : HasRealPairedStructure td u) (hv : HasRealPairedStructure td v) :
    HasRealPairedStructure td (u ∘ₕ v)

theorem map_ofReal_re_of_im_zero {A : Matrix (Fin n) (Fin n) ℂ}
    (h : ∀ i j, (A i j).im = 0) :
    (Matrix.of (fun i j => (A i j).re)).map ((↑) : ℝ → ℂ) = A

private theorem submatrix_mulVec_comp_perm (M : Matrix (Fin n) (Fin n) ℂ)
    (σ : Equiv.Perm (Fin n)) (v : Fin n → ℂ) :
    M.submatrix σ σ *ᵥ (v ∘ ⇑σ) = (M *ᵥ v) ∘ ⇑σ

private theorem starMC_comp_perm (td : TubalData n) (σ : Equiv.Perm (Fin n))
    (a b : Fin n → ℂ) :
    starMC (permuteTubalData td σ) (a ∘ ⇑σ) (b ∘ ⇑σ) = (starMC td a b) ∘ ⇑σ

private theorem starM_comp_perm (td : TubalData n) (σ : Equiv.Perm (Fin n))
    (a b : Fin n → ℝ) :
    starM (permuteTubalData td σ) (a ∘ ⇑σ) (b ∘ ⇑σ) = (starM td a b) ∘ ⇑σ

private theorem canonicalEquiv_inl_val {m k : ℕ} (hk : m + 2 * k = n)
    (i : Fin n) (hi : i.val < m) :
    canonicalEquiv m k hk (Sum.inl ⟨i.val, hi⟩) = i

private theorem canonicalEquiv_symm_lt {m k : ℕ} (hk : m + 2 * k = n)
    (i : Fin n) (hi : i.val < m) :
    (canonicalEquiv m k hk).symm i = Sum.inl ⟨i.val, hi⟩

private theorem canonicalM_mulVec_coord (m : ℕ) (hm : m ≤ n) (hpar : n % 2 = m % 2)
    (v : Fin n → ℂ) (i : Fin n) (hi : i.val < m) :
    (canonicalM n m hm hpar *ᵥ v) i = v i

private theorem canonicalMinv_mulVec_coord (m : ℕ) (hm : m ≤ n) (hpar : n % 2 = m % 2)
    (v : Fin n → ℂ) (i : Fin n) (hi : i.val < m) :
    (canonicalMinv n m hm hpar *ᵥ v) i = v i

private theorem canonicalEquiv_symm_ge {m k : ℕ} (hk : m + 2 * k = n)
    (i : Fin n) (hi : i.val ≥ m) :
    ∃ (r : Fin 2) (b : Fin k), (canonicalEquiv m k hk).symm i = Sum.inr (r, b)

private theorem canonicalM_pair_real_zero (m : ℕ) (hm : m ≤ n) (hpar : n % 2 = m % 2)
    (j i : Fin n) (hj : j.val ≥ m) (hi : i.val < m) :
    canonicalM n m hm hpar j i = 0

private theorem canonicalM_real_pair_zero (m : ℕ) (hm : m ≤ n) (hpar : n % 2 = m % 2)
    (i j : Fin n) (hi : i.val < m) (hj : j.val ≥ m) :
    canonicalM n m hm hpar i j = 0

private theorem canonicalMinv_pair_real_zero (m : ℕ) (hm : m ≤ n) (hpar : n % 2 = m % 2)
    (j i : Fin n) (hj : j.val ≥ m) (hi : i.val < m) :
    canonicalMinv n m hm hpar j i = 0

private theorem canonicalMinv_real_pair_zero (m : ℕ) (hm : m ≤ n) (hpar : n % 2 = m % 2)
    (i j : Fin n) (hi : i.val < m) (hj : j.val ≥ m) :
    canonicalMinv n m hm hpar i j = 0

private theorem pair_sq_sum_re (r s : Fin 2) :
    (∑ t : Fin 2, conjPairBlockInv s t * (conjPairBlock t r) ^ 2).re =
    if s = 0 then (if r = 0 then 1 / Real.sqrt 2 else -(1 / Real.sqrt 2)) else 0

private theorem canonicalEquiv_inr_ge {m k : ℕ} (hk : m + 2 * k = n)
    (r : Fin 2) (b : Fin k) :
    (canonicalEquiv m k hk (Sum.inr (r, b))).val ≥ m

private theorem ringHom_toAlgHom_apply (td : TubalData n)
    (φ : KM n td →+* ℝ) (x : KM n td) :
    ringHom_toAlgHom td φ x = φ x
